use rig::loaders::FileLoader;


// Glob: every Rust file in a directory, with each file's path.
let examples = FileLoader::with_glob("examples/*.rs")?
    .read_with_path()   // yields Result<(PathBuf, String), _>
    .ignore_errors()
    .into_iter();


// Directory: every file directly inside a folder.
let dir_files = FileLoader::with_dir("data/")?
    .read()             // yields Result<String, _>
    .ignore_errors();


// Bytes: content from any source, e.g. a download.
let from_bytes = FileLoader::from_bytes(b"hello".to_vec());

use rig::loaders::FileLoader;
use rig::providers::openai::{self, OpenAI};


let model = OpenAI::from_env()?.completion(openai::GPT_5_5);


let agent = FileLoader::with_glob("examples/*.rs")?
    .read_with_path()
    .ignore_errors()
    .into_iter()
    .fold(AgentBuilder::new(model), |builder, (path, content)| {
        builder.context(format!("Rust example {path:?}:\n{content}"))
    })
    .build();

use rig::loaders::PdfFileLoader;


let pages = PdfFileLoader::with_glob("docs/*.pdf")?
    .load_with_path()   // yields Result<(PathBuf, Document), _>
    .ignore_errors()
    .by_page()          // each document's pages, numbered
    .ignore_errors()    // yields (PathBuf, Vec<(usize, String)>)
    .into_iter();


for (path, doc_pages) in pages {
    for (page_no, text) in doc_pages {
        println!("{} page {page_no}: {} chars", path.display(), text.len());
    }
}

use rig::loaders::epub::EpubLoaderError;
use rig::loaders::{EpubFileLoader, StripXmlProcessor};


fn count_chapters() -> Result<(), EpubLoaderError> {
    let chapters = EpubFileLoader::<_, StripXmlProcessor>::with_glob("books/*.epub")?
        .load_with_path()
        .ignore_errors()
        .by_chapter()       // yields (PathBuf, Vec<(usize, String)>)
        .ignore_errors()
        .into_iter();


    for (path, book) in chapters {
        println!("{}: {} chapters", path.display(), book.len());
    }
    Ok(())
}

use rig::message::{DocumentMediaType, ImageMediaType, UserContent};
use rig::providers::anthropic::{self, Anthropic};


let agent = AgentBuilder::new(Anthropic::from_env()?.completion(anthropic::CLAUDE_SONNET_5_5))
    .build();


let pdf = std::fs::read("report.pdf")?;
let chart = std::fs::read("chart.png")?;


let message = Message::User {
    content: vec![
        UserContent::text("Summarize the report and explain the chart."),
        UserContent::document_raw(pdf, Some(DocumentMediaType::PDF)),
        UserContent::image_raw(chart, Some(ImageMediaType::PNG), None),
    ],
};


let answer = agent.prompt(message).await?.output();
println!("{answer}");
